toolScript:
let mode = 'rgb';
        let intervalId;
        let noiseInterval;
        let countdownId;
        let totalSeconds = 0;
        const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFFFF', '#000000', '#FFFF00', '#00FFFF', '#FF00FF'];
        function setMode(m, el) {
            mode = m;
            document.querySelectorAll('.pattern-card').forEach(c => c.classList.remove('active'));
            el.classList.add('active');
        }
        function updateLabel(val) {
            document.getElementById('duration-val').innerText = val + " min";
        }
        function startScrubber() {
            const mins = parseInt(document.getElementById('duration').value);
            totalSeconds = mins * 60;
            const overlay = document.getElementById('scrubber-overlay');
            overlay.style.display = 'block';
            // Request Fullscreen
            if (document.documentElement.requestFullscreen) {
                document.documentElement.requestFullscreen();
            }
            // Hide HUD after 3s
            const hud = document.getElementById('scrubber-hud');
            hud.style.opacity = '1';
            setTimeout(() => { hud.style.opacity = '0'; }, 3000);
            // Start Mode
            if (mode === 'rgb') {
                document.getElementById('noise-canvas').style.display = 'none';
                let i = 0;
                intervalId = setInterval(() => {
                    overlay.style.backgroundColor = colors[i];
                    i = (i + 1) % colors.length;
                }, 200); // 5Hz cycle
            } else {
                // Noise Mode
                overlay.style.backgroundColor = 'black';
                const canvas = document.getElementById('noise-canvas');
                canvas.style.display = 'block';
                startNoise(canvas);
            }
            // Start Timer
            updateTimerDisplay();
            countdownId = setInterval(() => {
                totalSeconds--;
                updateTimerDisplay();
                if (totalSeconds <= 0) stopScrubber();
            }, 1000);
            // Hide cursor
            document.body.style.cursor = 'none';
        }
        function updateTimerDisplay() {
            const m = Math.floor(totalSeconds / 60);
            const s = totalSeconds % 60;
            document.getElementById('time-left').innerText = `${m}:${s < 10 ? '0' + s : s}`;
        }
        function stopScrubber() {
            document.getElementById('scrubber-overlay').style.display = 'none';
            clearInterval(intervalId);
            cancelAnimationFrame(noiseInterval);
            clearInterval(countdownId);
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
            // Show cursor again
            document.body.style.cursor = 'default';
        }
        // Noise Generator (Canvas)
        function startNoise(canvas) {
            const ctx = canvas.getContext('2d');
            const resize = () => {
                canvas.width = window.innerWidth;
                canvas.height = window.innerHeight;
            };
            window.addEventListener('resize', resize);
            resize();
            const loop = () => {
                const w = canvas.width;
                const h = canvas.height;
                const idata = ctx.createImageData(w, h);
                const buffer32 = new Uint32Array(idata.data.buffer);
                const len = buffer32.length;
                for (let i = 0; i < len; i++) {
                    if (Math.random() < 0.5) {
                        buffer32[i] = 0xffffffff; // White
                    } else {
                        buffer32[i] = 0xff000000; // Black
                    }
                }
                ctx.putImageData(idata, 0, 0);
                noiseInterval = requestAnimationFrame(loop);
            };
            loop();
        }
        // Mouse movement wakes up HUD
        let wakeTimeout;
        document.addEventListener('mousemove', () => {
            if (document.getElementById('scrubber-overlay').style.display === 'block') {
                const hud = document.getElementById('scrubber-hud');
                hud.style.opacity = '1';
                clearTimeout(wakeTimeout);
                wakeTimeout = setTimeout(() => { hud.style.opacity = '0'; }, 2000);
            }
        });
